using IDSFintech.Api.DTOs; using IDSFintech.Api.Repositories; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace IDSFintech.Api.Controllers;
[ApiController,Authorize,Route("api/[controller]")] public sealed class ProductsController(IPortalRepository r):ControllerBase { [HttpGet] public async Task<IActionResult> All(string? search)=>Ok(new ApiResponse<object>("Products retrieved.",await r.ProductsAsync(search))); [HttpGet("{id:int}")] public async Task<IActionResult> One(int id)=>await r.ProductAsync(id) is { } x?Ok(new ApiResponse<object>("Product retrieved.",x)):NotFound(new{message="Product not found."}); [HttpPost,Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Add(ProductRequest x){var id=await r.AddProductAsync(x);return CreatedAtAction(nameof(One),new{id},new ApiResponse<object>("Product created.",await r.ProductAsync(id)));} [HttpPut("{id:int}"),Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Edit(int id,ProductRequest x)=>await r.UpdateProductAsync(id,x)?Ok(new{message="Product updated."}):NotFound(new{message="Product not found."}); [HttpDelete("{id:int}"),Authorize(Roles="CEO,Manager")] public async Task<IActionResult> Delete(int id){try{return await r.DeleteProductAsync(id)?NoContent():NotFound(new{message="Product not found."});}catch{return Conflict(new{message="A product with related records cannot be deleted."});} } }
